cards.solution:
public class Main {
    public static void main(String[] args) {
        String sandi = "Kopi2024";
        boolean adaKapital = false;
        boolean adaAngka = false;
        for (char c : sandi.toCharArray()) {
            if (Character.isUpperCase(c)) adaKapital = true;
            if (Character.isDigit(c)) adaAngka = true;
        }
        System.out.println(sandi.length() >= 8 && adaKapital && adaAngka);
    }
}

